# -*- coding: utf-8 -*-
from pathlib import Path
import html, json

ROOT=Path(__file__).resolve().parents[1]
DATA=ROOT/'aiio/weekend/materials/data/hermes-nca-aiio-100-original-questions.json'
OUT=ROOT/'aiio/weekend/materials/hermes-nca-aiio-100-question-blueprint-mock.html'
SOURCES={
'S1':('NVIDIA NCA-AIIO Certification & Exam Blueprint','https://www.nvidia.com/en-us/learn/certification/ai-infrastructure-operations-associate/'),
'S2':('NVIDIA NCA-AIIO Exam Study Guide (PDF)','https://dam-cdn.nvd.orangelogic.com/AssetLink/x874j05hy3m3r2sor84kpvp70750m468.pdf'),
'S3':('NVIDIA TensorRT','https://developer.nvidia.com/tensorrt'),
'S4':('NVIDIA TensorRT Documentation','https://docs.nvidia.com/deeplearning/tensorrt/latest/index.html'),
'S5':('NVIDIA GPU Operator Documentation','https://docs.nvidia.com/datacenter/cloud-native/gpu-operator/latest/index.html'),
'S6':('NVIDIA: Scaling Storage for AI','https://developer.nvidia.com/blog/tips-on-scaling-storage-for-ai-training-and-inferencing/'),
'S7':('NVIDIA: Large Language Models','https://blogs.nvidia.com/blog/what-are-large-language-models-used-for/'),
'S8':('IBM: Machine Learning','https://www.ibm.com/think/topics/machine-learning'),
'S9':('SAS: Machine Learning','https://www.sas.com/en_us/insights/analytics/machine-learning.html'),
'S10':('AWS: CPU vs GPU','https://aws.amazon.com/compare/the-difference-between-gpus-cpus/'),
'S11':('NVIDIA CUDA Documentation','https://docs.nvidia.com/cuda/'),
'S12':('NVIDIA NCCL Documentation','https://docs.nvidia.com/deeplearning/nccl/'),
'S13':('NVIDIA Triton Documentation','https://docs.nvidia.com/deeplearning/triton-inference-server/user-guide/docs/'),
'S14':('NVIDIA NGC Catalog','https://catalog.ngc.nvidia.com/'),
'S15':('NVIDIA DCGM Documentation','https://docs.nvidia.com/datacenter/dcgm/latest/'),
'S16':('NVIDIA MIG User Guide','https://docs.nvidia.com/datacenter/tesla/mig-user-guide/latest/'),
'S17':('NVIDIA Data Processing Unit','https://www.nvidia.com/en-us/networking/products/data-processing-unit/'),
'S18':('NVIDIA AI Enterprise Documentation','https://docs.nvidia.com/ai-enterprise/index.html#overview'),
}
LABEL={'essential':'Essential AI Knowledge','infrastructure':'AI Infrastructure','operations':'AI Operations'}
questions=json.loads(DATA.read_text(encoding='utf-8'))
assert len(questions)==100
assert [q['id'] for q in questions]==list(range(1,101))
assert {d:sum(q['domain']==d for q in questions) for d in LABEL}=={'essential':38,'infrastructure':40,'operations':22}

cards=[]
for q in questions:
    options=''.join(f'<label class="option"><input type="radio" name="q{q["id"]}" value="{i}"><span><b>{chr(65+i)}</b>{html.escape(choice)}</span></label>' for i,choice in enumerate(q['choices']))
    cites=' '.join(f'<a href="#source-{k}">[{k}]</a>' for k in q['source_keys'])
    cards.append(f'''<article class="question-card" id="q-{q['id']}" data-id="{q['id']}" data-domain="{q['domain']}" data-answer="{q['answer']}">
<header><span>QUESTION {q['id']:03d}</span><b>{LABEL[q['domain']]} · Objective {html.escape(q['objective'])}</b></header>
<h2>{html.escape(q['question'])}</h2><div class="options">{options}</div>
<section class="explanation" hidden><p><strong>正確答案：{chr(65+q['answer'])}</strong> — {html.escape(q['choices'][q['answer']])}</p><p>{html.escape(q['explanation'])}</p><p class="cite">核對來源：{cites}</p></section></article>''')

sources=''.join(f'<li id="source-{k}"><a class="source-link" href="{u}" target="_blank" rel="noopener noreferrer"><b>[{k}]</b> {html.escape(n)}</a></li>' for k,(n,u) in SOURCES.items())
DOC=f'''<!doctype html><html lang="zh-Hant"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="赫少原創 NCA-AIIO 100 題藍圖模擬題庫，依官方 38/40/22 配置。"><title>赫少版｜NCA-AIIO 100 題藍圖模擬題庫</title><style>
:root{{--green:#76b900;--black:#050705;--paper:#f7f9f3;--ink:#171b16;--muted:#687064;--line:#dce2d5;--amber:#f0ad00;--red:#dc4c4c}}*{{box-sizing:border-box}}html{{scroll-behavior:smooth}}body{{margin:0;overflow-x:hidden;background:var(--black);color:#fff;font:16px/1.65 Inter,"Noto Sans TC",system-ui,sans-serif}}a{{color:inherit}}.top{{position:sticky;top:0;z-index:20;background:rgba(0,0,0,.95);border-bottom:1px solid #30372e}}.topin{{max-width:1240px;margin:auto;padding:12px 20px;display:flex;gap:14px;align-items:center}}.brand{{font-weight:900;text-decoration:none}}.brand i{{font-style:normal;color:var(--green)}}button{{border:2px solid var(--green);background:transparent;color:#fff;font-weight:800;padding:8px 12px;cursor:pointer}}button.primary{{background:var(--green);color:#000}}#timer{{margin-left:auto;font:900 1.55rem ui-monospace,monospace;color:var(--green)}}.hero{{max-width:1240px;margin:auto;padding:65px 20px 42px;display:grid;grid-template-columns:1.4fr .6fr;gap:44px}}.hero>*{{min-width:0}}.kicker{{font-size:.72rem;letter-spacing:.15em;color:var(--green);font-weight:900}}h1{{font-size:clamp(2.6rem,6vw,5.6rem);line-height:1.02;letter-spacing:-.055em;margin:.15em 0}}.lead{{color:#c7cdc3;font-size:1.08rem}}.notice{{border-left:4px solid var(--amber);background:#211a06;color:#f6dfa1;padding:14px 16px}}.stats{{display:grid;grid-template-columns:1fr 1fr;gap:1px;background:#30372e;border:1px solid #30372e;align-self:end}}.stat{{background:#0d100d;padding:20px}}.stat b{{display:block;color:var(--green);font-size:2rem}}.toolbar{{position:sticky;top:62px;z-index:15;background:#0a0d0a;border-block:1px solid #30372e}}.toolbarin{{max-width:1240px;margin:auto;padding:12px 20px;display:flex;gap:8px;flex-wrap:wrap}}.toolbar button.active{{background:var(--green);color:#000}}main{{max-width:980px;margin:auto;padding:34px 20px 85px}}.question-card{{scroll-margin-top:130px;background:var(--paper);color:var(--ink);padding:28px;margin:0 0 22px;border-top:3px solid var(--green)}}.question-card>header{{display:flex;justify-content:space-between;gap:16px;border-bottom:1px solid var(--line);padding-bottom:10px;font-size:.72rem;letter-spacing:.08em}}.question-card>header b{{color:#527d00}}.question-card h2{{font-size:1.35rem;line-height:1.42}}.options{{display:grid;gap:9px}}.option{{display:block;cursor:pointer}}.option input{{position:absolute;opacity:0}}.option span{{display:flex;gap:12px;align-items:flex-start;background:#fff;border:1px solid var(--line);padding:12px 14px}}.option b{{display:grid;place-items:center;min-width:26px;height:26px;background:#e8eddf}}.option input:checked+span{{border:2px solid var(--green);padding:11px 13px;background:#f4fae9}}.question-card.correct{{border-color:var(--green)}}.question-card.wrong{{border-color:var(--red)}}.question-card.correct .option input:checked+span{{background:#e6f4cf}}.question-card.wrong .option input:checked+span{{background:#ffe5e5;border-color:var(--red)}}.explanation{{margin-top:16px;background:#101410;color:#fff;padding:16px;border-left:4px solid var(--green)}}.cite{{font-size:.78rem;color:#afb7aa}}.cite a{{color:var(--green);font-weight:800}}#result{{max-width:980px;margin:0 auto 20px;padding:0 20px}}.resultbox{{display:none;border:2px solid var(--green);padding:20px;background:#101410}}.resultbox.show{{display:block}}.resultbox b{{font-size:2rem;color:var(--green)}}.sources{{max-width:980px;margin:0 auto 80px;padding:0 20px}}.sourcebox{{border:1px solid #30372e;background:#0c0f0c;padding:28px}}.source-link{{text-underline-offset:4px;text-decoration-color:var(--green)}}footer{{border-top:1px solid #2b302a;text-align:center;color:#7c8679;padding:25px}}[hidden]{{display:none!important}}@media(max-width:800px){{.hero{{grid-template-columns:1fr}}.topin{{padding:9px;flex-wrap:wrap}}.brand{{font-size:.8rem}}#timer{{font-size:1.15rem}}.top button:not(.primary){{display:none}}.question-card{{padding:20px 15px}}.question-card>header{{display:block}}}}@media print{{.top,.hero,.toolbar,#result,.sources,footer{{display:none!important}}body{{background:#fff}}main{{max-width:none;padding:0}}.question-card{{page-break-inside:avoid;box-shadow:none}}.explanation{{display:block!important;color:#000;background:#fff;border:1px solid #aaa}}}}
</style></head><body><header class="top"><div class="topin"><a class="brand" href="hermes-nca-aiio-cert-pass-100-unit-reader.html"><i>赫少</i> NCA-AIIO 100Q</a><button id="timer-start">開始 60 分鐘</button><button class="primary" id="score">計算成績</button><span id="timer">60:00</span></div></header>
<section class="hero"><div><div class="kicker">ORIGINAL QUESTIONS · BLUEPRINT ALIGNED</div><h1>100 題<br>藍圖模擬題庫</h1><p class="lead">依 NVIDIA 官方 NCA-AIIO 藍圖原創：Essential 38 題、Infrastructure 40 題、Operations 22 題。可完整練 100 題，也可隨機抽 50 題模擬正式考試。</p><p class="notice">這是原創模擬題，非真實考題或未授權考古題；不能承諾必然通過。NVIDIA 官方目前列出的考試費為 <strong>$125 USD</strong>、50 題、60 分鐘，並非 $12；若你有折扣碼或特殊價格，請以結帳頁為準。</p></div><div class="stats"><div class="stat"><b>38</b>Essential</div><div class="stat"><b>40</b>Infrastructure</div><div class="stat"><b>22</b>Operations</div><div class="stat"><b>50 / 60</b>正式題數／分鐘</div></div></section>
<nav class="toolbar"><div class="toolbarin"><button class="active" data-filter="all">全部 100 題</button><button data-filter="essential">Essential 38</button><button data-filter="infrastructure">Infrastructure 40</button><button data-filter="operations">Operations 22</button><button id="mock50">隨機抽 50 題</button><button id="reset">清除作答</button><button onclick="window.print()">列印</button></div></nav><section id="result"><div class="resultbox" id="resultbox"><b id="resultscore">0 / 0</b><p id="resulttext"></p></div></section><main>{''.join(cards)}</main>
<section class="sources"><div class="sourcebox"><div class="kicker">VERIFIED SOURCES</div><h2>答案核對來源</h2><ol>{sources}</ol></div></section><footer>赫少原創版 · 非真實考題 · 2026</footer><script>
const cards=[...document.querySelectorAll('.question-card')],key='hermes-nca-aiio-100q-v1';let state=JSON.parse(localStorage.getItem(key)||'{{}}');function save(){{localStorage.setItem(key,JSON.stringify(state))}}cards.forEach(c=>{{let id=c.dataset.id;if(state[id]!==undefined){{let r=c.querySelector(`input[value="${{state[id]}}"]`);if(r)r.checked=true}}c.querySelectorAll('input').forEach(r=>r.addEventListener('change',()=>{{state[id]=+r.value;save()}}))}});function show(domain){{cards.forEach(c=>c.hidden=domain!=='all'&&c.dataset.domain!==domain)}}document.querySelectorAll('[data-filter]').forEach(b=>b.addEventListener('click',()=>{{document.querySelectorAll('[data-filter]').forEach(x=>x.classList.toggle('active',x===b));show(b.dataset.filter)}}));document.getElementById('mock50').addEventListener('click',()=>{{const take=(a,n)=>a.sort(()=>Math.random()-.5).slice(0,n),selected=new Set([...take(cards.filter(c=>c.dataset.domain==='essential'),19),...take(cards.filter(c=>c.dataset.domain==='infrastructure'),20),...take(cards.filter(c=>c.dataset.domain==='operations'),11)]);cards.forEach(c=>c.hidden=!selected.has(c));document.querySelectorAll('[data-filter]').forEach(x=>x.classList.remove('active'));window.scrollTo({{top:document.querySelector('.toolbar').offsetTop,behavior:'smooth'}})}});document.getElementById('score').addEventListener('click',()=>{{let visible=cards.filter(c=>!c.hidden),answered=0,correct=0;visible.forEach(c=>{{let checked=c.querySelector('input:checked'),ans=+c.dataset.answer;c.classList.remove('correct','wrong');if(checked){{answered++;if(+checked.value===ans){{correct++;c.classList.add('correct')}}else c.classList.add('wrong')}}c.querySelector('.explanation').hidden=false}});let pct=answered?Math.round(correct/visible.length*100):0,box=document.getElementById('resultbox');document.getElementById('resultscore').textContent=`${{correct}} / ${{visible.length}}（${{pct}}%）`;document.getElementById('resulttext').textContent=`已作答 ${{answered}} 題。建議連續兩次隨機 50 題達 85% 以上，再預約考試。`;box.classList.add('show');box.scrollIntoView({{behavior:'smooth'}})}});document.getElementById('reset').addEventListener('click',()=>{{state={{}};save();cards.forEach(c=>{{c.querySelectorAll('input').forEach(x=>x.checked=false);c.classList.remove('correct','wrong');c.querySelector('.explanation').hidden=true}});document.getElementById('resultbox').classList.remove('show')}});let sec=3600,t=null;document.getElementById('timer-start').addEventListener('click',e=>{{if(t)return;e.target.textContent='計時中';t=setInterval(()=>{{sec--;document.getElementById('timer').textContent=String(Math.floor(sec/60)).padStart(2,'0')+':'+String(sec%60).padStart(2,'0');if(sec<=0){{clearInterval(t);document.getElementById('score').click()}}}},1000)}});
</script></body></html>'''
OUT.write_text(DOC,encoding='utf-8')
print(f'wrote {OUT} questions={len(questions)}')
